// Lecture BACnet/IP de points connus, sans module externe.
// Device: 192.168.0.210 / deviceId 10000.
// Points: ANALOG_OUTPUT instances 6, 14, 22.
const DEVICE = { ip: "192.168.0.210", port: 47808, deviceId: 10000 };
const PROP_PRESENT_VALUE = 85;
const POINTS = [
    { objectName: "Space Temperature Setpoint BAS|rt-1", objectType: 1, objectTypeName: "ANALOG_OUTPUT", objectInstance: 6 },
    { objectName: "Space Temperature Setpoint BAS|rt-2", objectType: 1, objectTypeName: "ANALOG_OUTPUT", objectInstance: 14 },
    { objectName: "Space Temperature Setpoint BAS|rt-3", objectType: 1, objectTypeName: "ANALOG_OUTPUT", objectInstance: 22 }
];

function objectIdToBuffer(type, instance) {
    const value = ((type & 0x3ff) << 22) | (instance & 0x3fffff);
    return Buffer.from([(value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff]);
}
function contextUnsigned(tagNumber, value) {
    if (value <= 0xff) return Buffer.from([(tagNumber << 4) | 0x09, value]);
    if (value <= 0xffff) return Buffer.from([(tagNumber << 4) | 0x0a, (value >>> 8) & 0xff, value & 0xff]);
    return Buffer.from([(tagNumber << 4) | 0x0c, (value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff]);
}
function nextInvoke() {
    const current = flow.get("bacnetReadInvoke") || 1;
    flow.set("bacnetReadInvoke", current >= 255 ? 1 : current + 1);
    return current;
}
function buildReadProperty(point) {
    const invokeId = nextInvoke();
    const apdu = Buffer.concat([
        Buffer.from([0x00, 0x05, invokeId, 0x0c]), // confirmed request, max APDU, invokeId, ReadProperty
        Buffer.from([0x0c]), objectIdToBuffer(point.objectType, point.objectInstance),
        contextUnsigned(1, PROP_PRESENT_VALUE)
    ]);
    const npdu = Buffer.from([0x01, 0x04]); // BACnet version 1, expecting reply
    const body = Buffer.concat([npdu, apdu]);
    const bvlc = Buffer.from([0x81, 0x0a, (body.length + 4) >>> 8, (body.length + 4) & 0xff]);
    return {
        payload: Buffer.concat([bvlc, body]),
        ip: DEVICE.ip,
        port: DEVICE.port,
        topic: `bacnet/read/${DEVICE.deviceId}/analog-output/${point.objectInstance}/present-value`,
        bacnet: { device: DEVICE, point, propertyId: PROP_PRESENT_VALUE, invokeId }
    };
}

const pending = flow.get("bacnetReadPending") || {};
const messages = POINTS.map(point => {
    const read = buildReadProperty(point);
    pending[read.bacnet.invokeId] = read.bacnet;
    return read;
});
flow.set("bacnetReadPending", pending);
node.status({ fill: "blue", shape: "dot", text: `${messages.length} lectures envoyees vers ${DEVICE.ip}` });
return [messages];

// Decode les reponses ReadProperty-ACK pour present-value.
const BACNET_PORT = 47808;
const PROP_PRESENT_VALUE = 85;

function readUInt(buf, offset, len) {
    let v = 0;
    for (let i = 0; i < len; i++) v = (v << 8) | buf[offset + i];
    return v >>> 0;
}
function decodeObjectId(buf, offset) {
    const value = readUInt(buf, offset, 4);
    return { type: value >>> 22, instance: value & 0x3fffff };
}
function tagInfo(buf, offset) {
    if (offset >= buf.length) return null;
    const b = buf[offset];
    let tag = b >>> 4;
    const context = !!(b & 0x08);
    const lvt = b & 0x07;
    let header = 1;
    if (tag === 0x0f) { tag = buf[offset + header]; header++; }
    let len = lvt;
    if (lvt === 5) { len = buf[offset + header]; header++; }
    return { tag, context, lvt, len, valueOffset: offset + header, next: offset + header + len };
}
function skipNpdu(buf) {
    if (buf.length < 6 || buf[0] !== 0x81) return -1;
    let i = 4;
    if (buf[i++] !== 0x01) return -1;
    const control = buf[i++];
    if (control & 0x20) {
        i += 2;
        const dlen = buf[i++];
        i += dlen + 1;
    }
    if (control & 0x08) {
        i += 2;
        const slen = buf[i++];
        i += slen;
    }
    if (control & 0x80) return -1;
    return i;
}
function parseReadPropertyAck(buf, apduOffset) {
    if ((buf[apduOffset] >>> 4) !== 3) return null;
    const invokeId = buf[apduOffset + 1];
    const service = buf[apduOffset + 2];
    if (service !== 0x0c) return null;
    let i = apduOffset + 3;
    const tObj = tagInfo(buf, i);
    if (!tObj || !tObj.context || tObj.tag !== 0) return null;
    const object = decodeObjectId(buf, tObj.valueOffset);
    i = tObj.next;
    const tProp = tagInfo(buf, i);
    if (!tProp || !tProp.context || tProp.tag !== 1) return null;
    const propertyId = readUInt(buf, tProp.valueOffset, tProp.len);
    i = tProp.next;
    if (buf[i] !== 0x3e) return null; // opening tag [3]
    return { invokeId, object, propertyId, valueOffset: i + 1 };
}
function parseError(buf, apduOffset) {
    const pduType = buf[apduOffset] >>> 4;
    if (pduType !== 5 && pduType !== 6 && pduType !== 7) return null;
    return { invokeId: buf[apduOffset + 1], pduType, raw: buf.slice(apduOffset).toString("hex") };
}
function decodeApplicationValue(buf, offset) {
    const t = tagInfo(buf, offset);
    if (!t || t.context) return { value: null, type: "unknown", raw: buf.slice(offset).toString("hex") };
    if (t.tag === 4 && t.len === 4) return { value: buf.readFloatBE(t.valueOffset), type: "real" };
    if (t.tag === 5 && t.len === 8) return { value: buf.readDoubleBE(t.valueOffset), type: "double" };
    if (t.tag === 2) return { value: readUInt(buf, t.valueOffset, t.len), type: "unsigned" };
    if (t.tag === 3) return { value: readUInt(buf, t.valueOffset, t.len), type: "signed-or-bitstring" };
    if (t.tag === 9) return { value: readUInt(buf, t.valueOffset, t.len), type: "enumerated" };
    if (t.tag === 1) return { value: t.lvt === 1, type: "boolean" };
    if (t.tag === 7 && t.len >= 1) return { value: buf.slice(t.valueOffset + 1, t.valueOffset + t.len).toString("utf8"), type: "character-string" };
    if (t.tag === 0) return { value: null, type: "null" };
    return { value: null, type: `application-tag-${t.tag}`, raw: buf.slice(offset, t.next).toString("hex") };
}

const buf = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload || []);
const apduOffset = skipNpdu(buf);
if (apduOffset < 0) return null;
const pending = flow.get("bacnetReadPending") || {};

const ack = parseReadPropertyAck(buf, apduOffset);
if (ack) {
    const req = pending[ack.invokeId];
    if (!req || ack.propertyId !== PROP_PRESENT_VALUE) return null;
    delete pending[ack.invokeId];
    flow.set("bacnetReadPending", pending);
    const decoded = decodeApplicationValue(buf, ack.valueOffset);
    msg.topic = `bacnet/value/${req.device.deviceId}/${req.point.objectTypeName}/${req.point.objectInstance}`;
    msg.payload = {
        timestamp: new Date().toISOString(),
        deviceId: req.device.deviceId,
        ip: req.device.ip,
        objectName: req.point.objectName,
        objectType: req.point.objectTypeName,
        objectTypeId: req.point.objectType,
        objectInstance: req.point.objectInstance,
        property: "present-value",
        propertyId: PROP_PRESENT_VALUE,
        value: decoded.value,
        valueType: decoded.type
    };
    node.status({ fill: "green", shape: "dot", text: `${req.point.objectInstance} = ${decoded.value}` });
    return msg;
}

const err = parseError(buf, apduOffset);
if (err && pending[err.invokeId]) {
    const req = pending[err.invokeId];
    delete pending[err.invokeId];
    flow.set("bacnetReadPending", pending);
    msg.topic = `bacnet/error/${req.device.deviceId}/${req.point.objectInstance}`;
    msg.payload = { timestamp: new Date().toISOString(), point: req.point, error: err };
    node.status({ fill: "red", shape: "ring", text: `erreur instance ${req.point.objectInstance}` });
    return msg;
}
return null;

flow.set("bacnetReadPending", {});
flow.set("bacnetReadInvoke", 1);
node.status({ fill: "grey", shape: "ring", text: "contexte lecture efface" });
msg.payload = "Contexte de lecture BACnet efface";
return msg;
